// Lineage A, r1 E4: persistent batch-aligned rounds, fp32 h in TMEM, per-batch GRN counters, FP16x3 tcgen05.
// One cooperative launch. A round holds whole batches (bpr * HW <= 148 * 128 tokens); CTA c owns 128-token tile c of
// every round. Per round: x -> fp16 hi/lo (smem) -> GEMM1 swap-AB D1[hid][tok] = W1hi.Xhi + W1hi.Xlo + W1lo.Xhi in
// TMEM (512 cols) -> + b1, GELU, per-batch sumsq red.add -> per-batch counter -> s = 1 + gw G / (mean G + eps) ->
// h' = h s split hi/lo into MN-major smem -> GEMM2 swap-AB D2[c][tok] (main W2hi.h'hi, cross W2hi.h'lo + W2lo.h'hi in
// a separate accumulator, both in TMEM columns freed by h blocks 0/1) -> out = main + cross + b2 + W2.gb.
// Weights: phase 0 converts W1/W2 into fp16 hi/lo SW128 byte images (workspace), streamed by a 3 x 32 KB bulk ring.
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <stdint.h>


#define e4_launch lf_r1_a_e4_rounds_tmem_e4_launch
